cards.solution:
function Pesanan(menu, jumlah, harga) {
  this.menu = menu;
  this.jumlah = jumlah;
  this.total = jumlah * harga;
}
const p1 = new Pesanan("Nasi Goreng", 2, 15000);
const p2 = new Pesanan("Es Teh", 3, 5000);
console.log(`${p1.menu} x${p1.jumlah} = ${p1.total}`);
console.log(`${p2.menu} x${p2.jumlah} = ${p2.total}`);
